3-3")		return	end		-- 判断赠点	local nNeedEmoneyMono = tAugPromo_Data["EmoneyMono"][nIndex]	if Get_UserMonoEMoney() < nNeedEmoneyMono then		tNpcGossip[nNpcId]["Text311"] = string.format(tAugPromo_Text[nNpcId]["Text311"],nNeedEmoneyMono)		LinkNpcGossipFunc_New(nNpcId,"3-1")		return false	end		User_AddEMoneyMono(-nNeedEmoneyMono)	RewardTemplate_UseItemAndMsg(tAugPromo_Reward[nIndex])end--------------------------------------npc配置--------------------------------------------- 头像tNpcFace[4971] = 119tNpcGossip[21971] = tNpcGossip[21971] or DefaultNpc:new{}tNpcGossip[21971]["OptionHidden"] = 1tNpcGossip[21971]["DialogueText"] = tAugPromo_Text[21971]-- 活动前tNpcGossip[21971]["Text1-1"] = {111,112,113}tNpcGossip[21971]["tOption1-1"] = {1}tNpcGossip[21971]["ChkFunc1-1"] = function()	return CommonFunc_GetBeforeActivityTime(tAugPromo_Data["ActivityTime"])end-- 活动后tNpcGossip[21971]["Text1-2"] = {121}tNpcGossip[21971]["tOption1-2"] = {2}tNpcGossip[21971]["ChkFunc1-2"] = function()	return CommonFunc_GetAfterActivityTime(tAugPromo_Data["ActivityTime"])end-- 活动中tNpcGossip[21971]["Text1-3"] = {131,132,133,134,135,136,137,138,139,140,141,142,143}tNpcGossip[21971]["tOption1-3"] = {11,12,13,14,15,16,17,18}tNpcGossip[21971]["ChkFunc1-3"] = function()	-- 1颗金钢坚钻(赠)	local nEventType1 = tAugPromo_Reward[1]["EventType"]	local nDataType1 = tAugPromo_Reward[1]["DataType"]	local nTotalTimes1 = tAugPromo_Reward[1]["RewardTotalData"]	local nUsedTimes1 = math.floor(Get_UserStatisticValue(nEventType1,nDataType1)/10000)	local nRestTimes1 = nTotalTimes1 - nUsedTimes1	tNpcGossip[21971]["Text135"] = string.format(tAugPromo_Text[21971]["Text135"],nRestTimes1)		-- 1颗七星宝钻(赠)	local nEventType2 = tAugPromo_Reward[2]["EventType"]	local nDataType2 = tAugPromo_Reward[2]["DataType"]	local nTotalTimes2 = tAugPromo_Reward[2]["RewardTotalData"]	local nUsedTimes2 = math.floor(Get_UserStatisticValue(nEventType2,nDataType2)/10000)	local nRestTimes2 = nTotalTimes2 - nUsedTimes2	tNpcGossip[21971]["Text136"] = string.format(tAugPromo_Text[21971]["Text136"],nRestTimes2)		-- 1颗固化石(赠)	local nEventType3 = tAugPromo_Reward[3]["EventType"]	local nDataType3 = tAugPromo_Reward[3]["DataType"]	local nTotalTimes3 = tAugPromo_Reward[3]["RewardTotalData"]	local nUsedTimes3 = math.floor(Get_UserStatisticValue(nEventType3,nDataType3)/10000)	local nRestTimes3 = nTotalTimes3 - nUsedTimes3	tNpcGossip[21971]["Text137"] = string.format(tAugPromo_Text[21971]["Text137"],nRestTimes3)		-- 1颗+3赤炼石(赠)	local nEventType8 = tAugPromo_Reward[8]["EventType"]	local nDataType8 = tAugPromo_Reward[8]["DataType"]	local nTotalTimes8 = tAugPromo_Reward[8]["RewardTotalData"]	local nUsedTimes8 = math.floor(Get_UserStatisticValue(nEventType8,nDataType8)/10000)	local nRestTimes8 = nTotalTimes8 - nUsedTimes8	tNpcGossip[21971]["Text142"] = string.format(tAugPromo_Text[21971]["Text142"],nRestTimes8)		return Sys_ChkFullTime(tAugPromo_Data["ActivityTime"])endtNpcGossip[21971]["OptionPoint11"] = "2-1"tNpcGossip[21971]["OptionPoint12"] = "2-2"tNpcGossip[21971]["OptionPoint13"] = "2-3"tNpcGossip[21971]["OptionPoint14"] = "2-4"tNpcGossip[21971]["OptionPoint15"] = "2-5"tNpcGossip[21971]["OptionPoint16"] = "2-6"tNpcGossip[21971]["OptionPoint17"] = "2-7"tNpcGossip[21971]["OptionPoint18"] = "2-8"tNpcGossip[21971]["Text2-1"] = {211}tNpcGossip[21971]["tOption2-1"] = {211,3}tNpcGossip[21971]["OptionFunc211"] = "AugPromo_Buy</N>21971</N>1"tNpcGossip[21971]["OptionPoint3"] = "1-3"tNpcGossip[21971]["Text2-2"] = {221}tNpcGossip[21971]["tOption2-2"] = {221,3}tNpcGossip[21971]["OptionFunc221"] = "AugPromo_Buy</N>21971</N>2"tNpcGossip[21971]["Text2-3"] = {231}tNpcGossip[21971]["tOption2-3"] = {231,3}tNpcGossip[21971]["OptionFunc231"] = "AugPromo_Buy</N>21971</N>3"tNpcGossip[21971]["Text2-4"] = {241}tNpcGossip[21971]["tOption2-4"] = {241,3}tNpcGossip[21971]["OptionFunc241"] = "AugPromo_Buy</N>21971</N>4"tNpcGossip[21971]["Text2-5"] = {251}tNpcGossip[219